-- Card search filters run before pagination and retain listing visibility/block rules.
begin;
create or replace function public.exchange_search_listings(p_season text,p_star integer default null,p_type text default null,p_mode text default null,p_initiator text default null,p_online boolean default false,p_attempts boolean default false,p_limit integer default 20,p_offset integer default 0,p_receive integer default null,p_give integer default null) returns jsonb language sql stable security definer set search_path=pg_catalog as $$
with listings as (
 select p.user_id,p.game_id,p.display_name,p.avatar_url,ep.last_seen,coalesce(pref.rarity_mode,'Same Rarity') rarity_mode,coalesce(pref.trades_left_today,3) trades_left_today,
 (select max(i.updated_at) from public.card_inventory i where i.user_id=p.user_id and i.season_id=p_season and i.quantity>=2 and public.trade_card_available(p_season,i.card_number)) freshness,
 (select jsonb_agg(i.card_number order by i.card_number) from public.card_inventory i join public.album_cards c using(season_id,card_number) where i.user_id=p.user_id and i.season_id=p_season and i.quantity>=2 and public.trade_card_available(p_season,i.card_number) and (p_type is null or c.gold=(p_type='gold')) and (p_star is null or c.stars=p_star)) ft,
 (select coalesce(jsonb_agg(jsonb_build_object('give',a.card_number,'receive',b.card_number) order by a.card_number,b.card_number),'[]'::jsonb) from public.card_inventory yours join public.album_cards a on a.season_id=yours.season_id and a.card_number=yours.card_number cross join public.card_inventory theirs join public.album_cards b on b.season_id=theirs.season_id and b.card_number=theirs.card_number where yours.user_id=auth.uid() and exists(select 1 from public.profiles own where own.user_id=auth.uid() and own.game_id<>'') and yours.season_id=p_season and yours.quantity>=2 and theirs.user_id=p.user_id and theirs.season_id=p_season and theirs.quantity>=2 and public.trade_card_available(p_season,a.card_number) and public.trade_card_available(p_season,b.card_number) and (p_type is null or b.gold=(p_type='gold')) and (p_star is null or b.stars=p_star) and not exists(select 1 from public.card_inventory k where k.user_id=p.user_id and k.season_id=p_season and k.card_number=a.card_number and k.quantity>0) and not exists(select 1 from public.card_inventory k where k.user_id=auth.uid() and k.season_id=p_season and k.card_number=b.card_number and k.quantity>0) and public.trade_accepts(auth.uid(),p_season,a.stars,b.stars) and public.trade_accepts(p.user_id,p_season,b.stars,a.stars)) swaps
,
 (select coalesce(jsonb_agg(yours.card_number order by yours.card_number),'[]'::jsonb) from public.card_inventory yours join public.album_cards c on c.season_id=yours.season_id and c.card_number=yours.card_number where yours.user_id=auth.uid() and yours.season_id=p_season and yours.quantity>=2 and exists(select 1 from public.profiles own where own.user_id=auth.uid() and own.game_id<>'' and own.trade_enabled) and coalesce((select rarity_mode from public.album_trade_preferences where user_id=auth.uid() and season_id=p_season),'Same Rarity')<>'No Trading' and public.trade_card_available(p_season,yours.card_number) and (p_type is null or c.gold=(p_type='gold')) and (p_star is null or c.stars=p_star) and not exists(select 1 from public.card_inventory k where k.user_id=p.user_id and k.season_id=p_season and k.card_number=yours.card_number and k.quantity>0)) gifts
,
 (select coalesce(jsonb_agg(theirs.card_number order by theirs.card_number),'[]'::jsonb) from public.card_inventory theirs join public.album_cards c on c.season_id=theirs.season_id and c.card_number=theirs.card_number where theirs.user_id=p.user_id and theirs.season_id=p_season and theirs.quantity>=2 and auth.uid() is not null and public.trade_card_available(p_season,theirs.card_number) and (p_type is null or c.gold=(p_type='gold')) and (p_star is null or c.stars=p_star) and not exists(select 1 from public.card_inventory k where k.user_id=auth.uid() and k.season_id=p_season and k.card_number=theirs.card_number and k.quantity>0) and not exists(select 1 from public.card_inventory yours where yours.user_id=auth.uid() and yours.season_id=p_season and yours.quantity>=2 and public.trade_card_available(p_season,yours.card_number) and not exists(select 1 from public.card_inventory k where k.user_id=p.user_id and k.season_id=p_season and k.card_number=yours.card_number and k.quantity>0))) gift_requests
 from public.profiles p left join public.exchange_presence ep on ep.user_id=p.user_id left join public.album_trade_preferences pref on pref.user_id=p.user_id and pref.season_id=p_season where p.trade_enabled and p.game_id<>'' and coalesce((select preferences.rarity_mode from public.album_trade_preferences preferences where preferences.user_id=p.user_id and preferences.season_id=p_season),'Same Rarity')<>'No Trading' and p.user_id is distinct from auth.uid() and not public.exchange_blocked(auth.uid(),p.user_id) and (not p_online or ep.last_seen>now()-interval '90 seconds') and (not p_attempts or coalesce(pref.trades_left_today,3)>0) and (p_mode is null or coalesce(pref.rarity_mode,'Same Rarity')=p_mode) and (p_initiator is null or (p_initiator='them' and coalesce(pref.trades_left_today,3)>0) or (p_initiator='me' and auth.uid() is not null and coalesce((select mine.trades_left_today from public.album_trade_preferences mine where mine.user_id=auth.uid() and mine.season_id=p_season),3)>0))
),page as (select * from listings where (ft is not null or jsonb_array_length(gifts)>0 or p_give is not null)
 and (p_receive is null or ft @> jsonb_build_array(p_receive))
 and (p_give is null or (exists(select 1 from public.album_cards c where c.season_id=p_season and c.card_number=p_give and public.trade_card_available(p_season,c.card_number) and (p_receive is not null or ((p_star is null or c.stars=p_star) and (p_type is null or c.gold=(p_type='gold'))))) and not exists(select 1 from public.card_inventory owned where owned.user_id=listings.user_id and owned.season_id=p_season and owned.card_number=p_give and owned.quantity>0)))
 order by freshness desc,user_id limit least(50,greatest(1,p_limit)) offset greatest(0,p_offset))
select coalesce(jsonb_agg(jsonb_build_object('id',user_id,'uid',game_id,'name',display_name,'avatar',avatar_url,'updated_at',freshness,'online',coalesce(last_seen>now()-interval '90 seconds',false),'last_seen',last_seen,'rarity_mode',rarity_mode,'trades_left_today',trades_left_today,'ft',ft,'swaps',swaps,'gifts',gifts,'gift_requests',gift_requests) order by freshness desc,user_id),'[]'::jsonb) from page
$$;
revoke all on function public.exchange_search_listings(text,integer,text,text,text,boolean,boolean,integer,integer,integer,integer) from public;
grant execute on function public.exchange_search_listings(text,integer,text,text,text,boolean,boolean,integer,integer,integer,integer) to anon,authenticated;


notify pgrst, 'reload schema';
commit;
